<template>
  <v-card class="pa-6 form-card">
    <div class="primary form-top-bar" />
    <div class="d-flex position-relative pb-4">
      <v-btn
        icon
        @click="goBack"
        v-track:click="{
          category: 'Signup',
          screen: 'Login',
          name: 'Change country',
        }"
      >
        <v-icon color="primary">mdi-arrow-left</v-icon>
      </v-btn>
      <FormattedText type="text-caption" class="centered-element">
        <span>
          {{ getTranslatedText('starterLayout.common.youSelected') }}
          {{ country }}
        </span>
        <router-link
          to="/welcome"
          v-track:click="{
            category: 'Signup',
            screen: 'Login',
            name: 'Change country',
          }"
        >
          <span>{{ getTranslatedText('starterLayout.common.change') }}</span>
        </router-link>
      </FormattedText>
    </div>
    <v-card-title class="flex-column justify-center pt-1">
      <FormattedText type="text-h6" intl value="starterLayout.login.title" />
    </v-card-title>
    <v-card-subtitle class="text-center">
      <FormattedText type="text-h6">
        <span>
          {{ getTranslatedText('starterLayout.common.preSubtitle') }}
        </span>
        <router-link
          to="/sign-up"
          v-track:click="{
            category: 'Signup',
            screen: 'Login',
            name: 'Go to email signup',
          }"
        >
          <span class="primary--text">
            {{ getTranslatedText('starterLayout.login.subtitle') }}
          </span>
        </router-link>
      </FormattedText>
    </v-card-subtitle>

    <v-card-text class="text--primary mt-6">
      <Form ref="loginForm" :config="formConfig" />
      <div class="text-center loader-errors-space">
        <transition-group appear name="fade" v-if="fetching">
          <v-progress-circular
            v-if="fetching"
            class="mt-6"
            size="55"
            indeterminate
            color="primary"
            key="progress"
          />
        </transition-group>
        <transition appear name="fade" v-else-if="error">
          <v-alert text type="error" class="my-0">
            <FormattedText type="text-caption" intl :value="errorMessage" />
          </v-alert>
        </transition>
      </div>
    </v-card-text>

    <v-card-actions>
      <CustomButton
        className="submit-button"
        block
        large
        rounded
        :disabled="$v.$invalid || isLoginProcess"
        type="submit"
        :form="formConfig.id"
        @click="formConfig.onSubmit"
        text="starterLayout.login.submit"
        textType="text-subtitle-2"
        textClass="text-capitalize"
        intl
      />
    </v-card-actions>
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import LOGIN_EVENTS from '@/config/events/login'
import RESTORE_EVENTS from '@/config/events/restore'
import PUBSUB_EVENTS from '@/config/events/pubsub'
import countries from '@/config/countries'

import { cleanObjectObserver } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import accountActions from '@/store/account/actions.types'

import Form from '@/components/shared/Form'
import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'
import setConfig from '@/components/AuthViews/LoginView/LoginViewForm/config'

export default {
  name: 'LoginViewForm',
  components: {
    Form,
    FormattedText,
    CustomButton,
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      auxValidators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('account', ['fetching', 'error', 'errorMessage']),
    ...mapState('app', ['countrySelected']),
    isLoginProcess() {
      return this.loginProcess
    },
    formConfig: function() {
      return setConfig(
        {
          inputs: this.inputs,
          v: this.$v.inputs,
        },
        {
          submit: this.submit,
          onClickRememberPassword: this.openRememberPassword,
        }
      )
    },
    country() {
      return countries[this.countrySelected].name
    },
  },
  methods: {
    ...mapActions('account', [
      accountActions.resetErrorStatus,
      accountActions.setFetching,
      accountActions.setAccountFetchingStatus,
      accountActions.setPosDataAfterLogin,
      accountActions.setAccountLoginError,
    ]),
    ...mapActions('app', [
      appActions.setRememberPasswordDialogStatus,
      appActions.setConfirmDeviceChangeDialogStatus,
    ]),
    goBack() {
      this.$router.go(-1)
    },
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
    setProperties() {
      this.formConfig.fields.forEach(field => {
        if (field.type.includes('selector'))
          this.$set(this.inputs, field.id, null)
        else if (field.type !== 'formattedText')
          this.$set(this.inputs, field.id, '')
        if (field.validators) {
          this.$set(
            this.auxValidators.inputs,
            field.id,
            Array.isArray(field.validators)
              ? field.validators
              : {
                  ...cleanObjectObserver(field.validators),
                }
          )
        }
      })
    },
    getValidators() {
      let object = { inputs: {} }
      Object.assign(object.inputs, this.auxValidators.inputs)
      object.inputs.account = {
        ...cleanObjectObserver(
          this.inputs.account.includes('@')
            ? this.auxValidators.inputs.account[0]
            : this.auxValidators.inputs.account[1]
        ),
      }
      return object
    },
    submit() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Signup',
        screen: 'Login',
        name: 'Submit',
      })
      this[accountActions.setFetching](true)
      this.inputs.country = this.countrySelected
      rendererEventsService.send(LOGIN_EVENTS.channel, {
        event: LOGIN_EVENTS.events.accountLoginProcess.name,
        data: { credentials: this.inputs, online: navigator.onLine },
      })
    },
    openRememberPassword() {
      this[appActions.setRememberPasswordDialogStatus](true)
    },
  },
  watch: {
    $data: {
      handler: function() {
        this[accountActions.resetErrorStatus]()
      },
      deep: true,
    },
    'inputs.account'() {
      this.validators = this.getValidators()
    },
  },
  validations() {
    return this.validators
  },
  mounted() {
    this.setProperties()
    rendererEventsService.subscribe(
      LOGIN_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [LOGIN_EVENTS.events.accountLoginProcess.replies.start]: () => {
            this[accountActions.setAccountFetchingStatus](true)
          },
          [LOGIN_EVENTS.events.accountLoginProcess.replies.error]: () => {
            this[accountActions.setAccountFetchingStatus](false)
            this[accountActions.setAccountLoginError](payload.error)
            if (payload.error.error === 'Connection error')
              notificationsService.showError(
                payload.error.message,
                this.$vuetify.lang,
                { timeout: 10000 }
              )
          },
          [LOGIN_EVENTS.events.accountLoginProcess.replies.success]: () => {
            rendererEventsService.send(PUBSUB_EVENTS.channel, {
              event: PUBSUB_EVENTS.events.updatePosInfo.name,
              data: { pos: payload.data.pos },
            })
            this.$track({
              type: 'system',
              action: 'api_call',
              category: 'Signup',
              screen: 'Login',
              name: 'Start restore process',
            })
            this.loginProcess = true
            this[accountActions.setPosDataAfterLogin]({
              posData: payload.data,
              pendingSyncOps: 1,
            })
            rendererEventsService.send(RESTORE_EVENTS.channel, {
              event: RESTORE_EVENTS.events.restoreProcess.name,
              data: { posData: payload.data },
            })
            this.$router.push({ name: 'Restore' })
          },
          [LOGIN_EVENTS.events.accountLoginProcess.replies
            .confirmDeviceChange]: () => {
            this[appActions.setConfirmDeviceChangeDialogStatus]({
              isOpen: true,
              data: payload.data,
            })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    if (this.$route.query && this.$route.query.account) {
      this.inputs.account = this.$route.query.account
      setTimeout(
        () => this.$refs.loginForm.$refs.password[0].$children[0].focus(),
        250
      )
    }
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(LOGIN_EVENTS.replyChannel)
  },
}
</script>

<style>
.form-card {
  border-radius: 8px !important;
  position: relative;
}
.form-top-bar {
  height: 8px;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}
.v-select.v-select--is-menu-active .v-input__icon--append .v-icon {
  transform: rotate(0);
}
.loader-errors-space {
  height: 105px;
}
.submit-button {
  min-width: 100% !important;
}
.fade-enter {
  opacity: 0;
}
.fade-enter-active {
  transition: opacity 2s ease-out;
}

.position-relative {
  position: relative;
}

.centered-element {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}
</style>
