import { required, maxLength, email } from 'vuelidate/lib/validators'

import { numericAccount } from '@/tools/customValidations'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'account',
      type: 'account',
      className: 'mb-3',
      validators: [
        { required, email },
        { required, numericAccount, maxLength: maxLength(10) },
        { required },
      ],
      autofocus: true,
    },
    {
      id: 'password',
      type: 'password',
      className: 'mb-3',
      validators: { required },
    },
    {
      id: 'text',
      type: 'textLink',
      onClick: methods.onClickRememberPassword,
      class: 'text-center mb-3',
      textType: 'text-subtitle-2',
      color: 'primary',
      intl: true,
      value: 'starterLayout.login.passwordRemember',
    },
  ],
  id: 'login-form',
  onSubmit: () => methods.submit(),
})

export default setConfig
